let getDescriptor = (obj: any, method: string | symbol | number) =>
  Object.getOwnPropertyDescriptor(obj, method)

let getDescriptorFromChain = (
  obj: any,
  method: string | symbol | number
): PropertyDescriptor | undefined => {
  let current: any = obj
  while (current && current !== Object.prototype && current !== Function.prototype) {
    const desc = Object.getOwnPropertyDescriptor(current, method)
    if (desc) return desc
    current = Object.getPrototypeOf(current)
  }
  return undefined
}

